VALUES (21259, 'tt0086429', NULL, 'Testament', 'Testament', 'movie', 1983, 'https://image.tmdb.org/t/p/w500/sIc7cgiGi1p4YK4zFEiObCUztXj.jpg', 'https://image.tmdb.org/t/p/original/teBOQUIRnsSNVX7cZzb07Kvyw8F.jpg', 'It''s just another day in the small town of Hamlin until something disastrous happens. Suddenly, news breaks that a series of nuclear warheads has been dropped along the Eastern Seaboard and, more locally, in California. As people begin coping with the devastating aftermath of the attacks — many suffer radiation poisoning — the Wetherly family tries to survive.', NULL, NULL, 4.3419, 6.4, 0, 10.51, '2026-10-20 20:06:54', '2026-10-20 20:06:54')
