VALUES (428449, 'tt6265828', NULL, 'A Ghost Story', 'A Ghost Story', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/rp5JPIyZi9sMob15l46zNQLe5cO.jpg', 'https://image.tmdb.org/t/p/original/2y2aqaScd7jsUee0ddI1iRNgwGq.jpg', 'Recently deceased, a white-sheeted ghost returns to his suburban home to console his bereft wife, only to find that in his spectral state he has become unstuck in time, forced to watch passively as the life he knew and the woman he loves slowly slip away.', NULL, NULL, 3.5462, 7.064, 0, 3.34034482758620683e+01, '2026-07-15 12:01:52', '2026-10-20 20:06:54')
