VALUES (11507, 'tt0086984', NULL, 'Body Double', 'Body Double', 'movie', 1984, 'https://image.tmdb.org/t/p/w500/lRFm5P2AdOGpELwm3HHhmUz6k5I.jpg', 'https://image.tmdb.org/t/p/original/h5QkdbRmG2VodOCSB0QMhSGcCkI.jpg', 'After losing an acting role and his girlfriend, Jake Scully finally catches a break: he gets offered a gig house-sitting in the Hollywood Hills. While peering through the beautiful home''s telescope one night, he spies a gorgeous woman dancing in her window. But when he witnesses the girl''s murder, it leads Scully through the netherworld of the adult entertainment industry on a search for answers—with porn actress Holly Body as his guide.', NULL, NULL, 7.6365, 6.74, 0, 3.88236363636363606e+01, '2026-07-20 01:02:04', '2026-10-20 20:06:54')
