VALUES (222935, 'tt2582846', NULL, 'The Fault in Our Stars', 'The Fault in Our Stars', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/kcVuktIlrn9SAN1uBmPDnocTQmF.jpg', 'https://image.tmdb.org/t/p/original/oQaVV7p916HO5MDI820zzs1pin9.jpg', 'Despite the tumor-shrinking medical miracle that has bought her a few years, Hazel has never been anything but terminal, her final chapter inscribed upon diagnosis. But when a patient named Augustus Waters suddenly appears at Cancer Kid Support Group, Hazel''s story is about to be completely rewritten.', NULL, NULL, 8.2504, 7.591, 0, 10.45, '2026-07-20 04:02:06', '2026-10-20 20:06:54')
