VALUES (46633, 'tt0200659', NULL, 'Ghostwatch', 'Ghostwatch', 'movie', 1992, 'https://image.tmdb.org/t/p/w500/h5nOIZbO3J7STIOZumW00BxU6DC.jpg', 'https://image.tmdb.org/t/p/original/iMedTQJ3sbRu3EmfTO15zJrdlEe.jpg', 'For Halloween 1992, the BBC decides to broadcast an investigation into the supernatural, hosted by TV chat-show legend Michael Parkinson. Parky (assisted by Mike Smith, Sarah Greene & Craig Charles) and a camera crew attempt to discover the truth behind the most haunted house in Britain. This ground-breaking live television experiment does not go as planned, however.', NULL, NULL, 2.0844, 7.029, 0, 1.4789090909090909e+01, '2026-07-21 03:32:24', '2026-10-20 20:06:54')
